/* @autogenerated */
import { fakeAsync, tick } from '@angular/core/testing';
import { HttpParams } from '@angular/common/http';
import { BehaviorSubject, first, of, switchMap } from 'rxjs';
import { ApiProvider } from './api.provider';
import { ApiService } from '@shared/data/api/api.service';
import { LongTask } from '@shared/data/long-task.model';

describe('ApiProvider', () => {
  const task = (detailStatus: LongTask['detailStatus']): LongTask => ({ uid: 'u1', detailStatus, steps: [] });

  function build(api: Partial<Record<keyof ApiService, jasmine.Spy>>) {
    return new ApiProvider<any, any>('uid', api as unknown as ApiService, 'http://svc/items', 'http://svc/acl/items');
  }

  it('encodes the key in item urls', () => {
    const api = {
      get: jasmine.createSpy('get').and.returnValue(of({})),
      put: jasmine.createSpy('put').and.returnValue(of({})),
      patch: jasmine.createSpy('patch').and.returnValue(of({})),
      delete: jasmine.createSpy('delete').and.returnValue(of({})),
    };
    const provider = build(api);

    provider.retrieve('a/b c').subscribe();
    provider.update('a/b c', {}).subscribe();
    provider.patch('a/b c', {}, 'enable').subscribe();
    provider.delete('a/b c').subscribe();
    provider.acl('a/b c').subscribe();

    expect(api.get.calls.argsFor(0)[0]).toBe('http://svc/items/a%2Fb%20c');
    expect(api.put.calls.mostRecent().args[0]).toBe('http://svc/items/a%2Fb%20c');
    expect(api.patch.calls.mostRecent().args[0]).toBe('http://svc/items/a%2Fb%20c/enable');
    expect(api.delete.calls.mostRecent().args[0]).toBe('http://svc/items/a%2Fb%20c');
    expect(api.get.calls.argsFor(1)[0]).toBe('http://svc/acl/items/a%2Fb%20c');
  });

  it('takes the next page from the next link of a full page', (done) => {
    const items = Array.from({ length: 10 }, (_, i) => ({ uid: 'u' + i }));
    const api = {
      get: jasmine
        .createSpy('get')
        .and.returnValue(of({ items, next: '?limit=10&since-uid=bb7da003-56d3-1a1a-aad0-ee2ef053b671' })),
    };

    build(api)
      .list({ limit: 10 })
      .subscribe((slide) => {
        expect(slide).toEqual({
          hasNext: true,
          next: { limit: '10', 'since-uid': 'bb7da003-56d3-1a1a-aad0-ee2ef053b671' },
          content: items,
        });
        done();
      });
  });

  it('treats a page shorter than the limit as the last one, even with a next link', (done) => {
    const api = {
      get: jasmine
        .createSpy('get')
        .and.returnValue(of({ items: [{ uid: 'a' }, { uid: 'b' }, { uid: 'c' }], next: '?limit=10&since-uid=c' })),
    };

    build(api)
      .list({ limit: 10 })
      .subscribe((slide) => {
        expect(slide.hasNext).toBeFalse();
        done();
      });
  });

  it('has no next page without the next link', (done) => {
    const api = { get: jasmine.createSpy('get').and.returnValue(of({ items: [] })) };

    build(api)
      .list({ limit: 10 })
      .subscribe((slide) => {
        expect(slide.hasNext).toBeFalse();
        expect(slide.next).toEqual({});
        done();
      });
  });

  it('maps the acl response', (done) => {
    const api = {
      get: jasmine.createSpy('get').and.returnValue(
        of({
          allows: { edit: { allowed: true, reason: 'owner' }, drop: { name: 'delete', allowed: false } },
          fields: { noVisibles: ['secret'] },
        }),
      ),
    };
    build(api)
      .acl(null)
      .subscribe((acl) => {
        expect(api.get).toHaveBeenCalledWith('http://svc/acl/items');
        expect(acl.allows).toEqual([
          { name: 'edit', allowed: true, description: 'owner' },
          { name: 'delete', allowed: false, description: undefined },
        ]);
        expect(acl.fields).toEqual({ noVisibles: ['secret'] });
        done();
      });
  });

  it('sends a single DELETE when the context changes while polling a mass delete', fakeAsync(() => {
    // Simula ApiService real: get reactivo al contexto, delete con una única instantánea.
    const context$ = new BehaviorSubject<string>('t1');
    const statuses = [task('PROCESSING'), task('PROCESSING'), task('FINISHED')];
    const deleteSpy = jasmine.createSpy('delete').and.returnValue(of({ uid: 'u1' }));
    const api = {
      delete: jasmine.createSpy('deleteCmd').and.callFake((url: string, params: HttpParams) =>
        context$.pipe(
          first(),
          switchMap(() => deleteSpy(url, params)),
        ),
      ),
      get: jasmine.createSpy('get').and.callFake(() => context$.pipe(switchMap(() => of(statuses.shift()!)))),
    };
    const values: LongTask[] = [];

    build(api)
      .deleteAllForQuery({ uids: ['1', '2'] })
      .subscribe((v) => values.push(v));

    tick(1000);
    context$.next('t2');
    tick(60_000);

    expect(deleteSpy).toHaveBeenCalledTimes(1);
    expect(api.get).toHaveBeenCalledWith('http://svc/items/~/delete-status/u1');
    expect(values.map((v) => v.detailStatus)).toEqual(['PROCESSING', 'PROCESSING', 'FINISHED']);
  }));

  it('emits TIMEOUT when the mass patch never finishes', fakeAsync(() => {
    const api = {
      patch: jasmine.createSpy('patch').and.returnValue(of({ uid: 'u1' })),
      get: jasmine.createSpy('get').and.returnValue(of(task('PROCESSING'))),
    };
    const values: LongTask[] = [];
    let completed = false;

    build(api)
      .patchAllForQuery('enable', { uids: ['1'] }, { enabled: true })
      .subscribe({ next: (v) => values.push(v), complete: () => (completed = true) });

    tick(5 * 60_000);

    expect(api.patch).toHaveBeenCalledTimes(1);
    expect(api.get).toHaveBeenCalledWith('http://svc/items/~/enable-status/u1');
    expect(values[values.length - 1].detailStatus).toBe('TIMEOUT');
    expect(completed).toBeTrue();
  }));
});
